import * as React from "react";
import { type VariantProps } from "class-variance-authority";
declare const buttonVariants: (props?: ({
    variant?: "primary" | "pill" | "brand" | "outline" | "outline-brand" | "ghost" | "on-brand" | "pill-outline" | "pill-on-brand" | null | undefined;
    size?: "sm" | "md" | "icon" | null | undefined;
} & import("class-variance-authority/types").ClassProp) | undefined) => string;
type ButtonProps = React.ComponentProps<"button"> & VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
};
declare function Button({ className, variant, size, asChild, type, ...props }: ButtonProps): React.JSX.Element;
export { Button, buttonVariants };

